    x = observation.get('position', [0, 0])[0] if isinstance(observation.get('position', []), list) else 0
    y = observation.get('position', [0, 0])[1] if isinstance(observation.get('position', []), list) else 0

    # Sensor grid or nearby info
    grid = observation.get('grid', None)
    enemies = observation.get('enemies', [])
    resources = observation.get('resources', [])
    owned = observation.get('owned', False)
    width = observation.get('width', 0)
    height = observation.get('height', 0)

    # Initialize move to stay
    dx, dy = 0, 0

    # Helper: clamp within bounds if bounds present
    def in_bounds(nx, ny):
        if width and height:
            return 0 <= nx < width and 0 <= ny < height
        return True

    # Priority heuristics:
    # 1) If resource nearby, move towards it
    if resources:
        # Find closest resource
        best = None
        bestd = float('inf')
        for r in resources:
            rx = r.get('x', 0)
            ry = r.get('y', 0)
            d = abs(rx - x) + abs(ry - y)
            if d < bestd:
                bestd = d
                best = (rx, ry)
        if best is not None and bestd > 0:
            rx, ry = best
            if rx > x and in_bounds(x+1, y): dx, dy = 1, 0
            elif rx < x and in_bounds(x-1, y): dx, dy = -1, 0
            elif ry > y and in_bounds(x, y+1): dx, dy = 0, 1
            elif ry < y and in_bounds(x, y-1): dx, dy = 0, -1
            return [dx, dy]

    # 2) If an enemy is nearby, try to move away or toward if pursuit
    if enemies:
        # Simple retreat: pick the farthest direction from any enemy
        best_move = None
        best_dist = -1
        for vx in (-1, 0, 1):
            for vy in (-1, 0, 1):
                if vx == 0 and vy == 0:
                    continue
                nx, ny = x + vx, y + vy
                if not in_bounds(nx, ny):
                    continue
                min_e_dist = min(abs(e.get('x', 0) - nx) + abs(e.get('y', 0) - ny) for e in enemies)
                if min_e_dist > best_dist:
                    best_dist = min_e_dist
                    best_move = (vx, vy)
        if best_move:
            return [best_move[0], best_move[1]]

    # 3) Otherwise, try neutral exploration: small random-like deterministic pattern
    # Use a simple deterministic offset cycle without randomness
    cycle = (observation.get('step', 0)) % 4
    if cycle == 0:
        dx, dy = 1, 0
    elif cycle == 1:
        dx, dy = -1, 0
    elif cycle == 2:
        dx, dy = 0, 1
    else:
        dx, dy = 0, -1

    # Ensure within bounds if hints present
    nx, ny = x + dx, y + dy
    if not in_bounds(nx, ny):
        dx, dy = 0, 0

    return [dx, dy]

